/**
 * Generate sample review records with realistic timestamps.
 * 
 * Returns partial ReviewRun objects (without id, orgId, createdAt) 
 * which will be filled in by the store when seeding.
 */
export function generateSampleReviews(): Omit<ReviewRun, "id" | "orgId" | "createdAt">[] {
  return sampleReviewTemplates.map((template, index) => {
    const createdAt = new Date();
    createdAt.setDate(createdAt.getDate() - template.daysAgo);
    createdAt.setHours(10 + index, 30, 0, 0); // Stagger times for realism
    
    return {
      brandId: template.brandId,
      brandName: template.brandName,
      brandIsDemo: true,
      createdBy: DEMO_USER_ID,
      ruleSnapshot: [], // Will be filled by seed function with actual rules
      contentFingerprint: "", // Will be calculated by seed function
      contentLength: template.content.length,
      content: template.content,
      summary: { total: 0, errors: 0, warnings: 0 }, // Will be calculated by seed function
      outcome: "no_rules_triggered" as const, // Will be updated by seed function
      findings: [], // Will be filled by seed function
      // NOTE: createdAt will be set by seed function
    };
  });
}
